"""真机验证「额外峰值显存」这个新观测量 (docs/research/44)

在控制端跑 (会触发 deploy(), 需要能连到 GPU 机器):
    python3 benchmarks/measurement/measure_peak_memory.py

外部依据 (✅ 一手核过 arXiv 2607.16241 abstract 原句):
  * "enabling Tensor Core acceleration with TF32 provides a more realistic estimation
    of execution on modern GPUs."
  * "the best-performing model (GPT-5.5) achieves a 0.88x geometric mean speedup,
    significantly lower than the 1.43x speedup"  ← 基线换成 TF32 打开的 PyTorch 之后
  * "On the memory front, 28% of GPU kernels generated by the best model increase
    peak GPU memory usage."

前两条对应我们的**基线选择** (下面第 3 个 case 复核它真的选了 tf32 档),
第三条对应 runner 新加的 `_additional_peak_bytes`。本项目的 L3 此前对显存是零测量。

⚠️ 这个探针的**第一问不是「核吃多少显存」, 而是「量具看得见吗」** —— 显存与时间不同,
它是确定性的, 所以可以用一次已知体积的分配做绝对标定 (case 2)。量不出已知的那份,
后面所有 ratio 都是空的。
"""
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from operator_agent.execute.remote_executor import RemoteExecutor
from operator_agent.core.schemas import (ConstraintSpec, Precision, SourceSpec, TargetSpec,
                                    TaskComplexity, TaskSchema, TaskType)
from operator_agent.decide.verifier import Verifier

MM = '''
import torch, triton, triton.language as tl

@triton.jit
def _mm(A, B, C, M, N, K, BM: tl.constexpr, BN: tl.constexpr, BK: tl.constexpr):
    pm = tl.program_id(0); pn = tl.program_id(1)
    om = pm * BM + tl.arange(0, BM); on = pn * BN + tl.arange(0, BN)
    acc = tl.zeros((BM, BN), dtype=tl.float32)
    for k0 in range(0, K, BK):
        ok = k0 + tl.arange(0, BK)
        a = tl.load(A + om[:, None] * K + ok[None, :])
        b = tl.load(B + ok[:, None] * N + on[None, :])
        acc = tl.dot(a, b, acc)
    tl.store(C + om[:, None] * N + on[None, :], acc.to(C.dtype.element_ty))

def kernel(A, B):
    M, K = A.shape; N = B.shape[1]
    C = torch.empty((M, N), device=A.device, dtype=A.dtype)
    _mm[(M // 64, N // 64)](A, B, C, M, N, K, BM=64, BN=64, BK=32)
    return C
'''

# 对照臂: 与上面同构, 但把同一份结果**额外**写进一块 fp32 缓冲。1024² 时这块缓冲是
# 1024*1024*4 = 4.0 MiB, 而候选与基线的差值就应当是这 4.0 MiB。
# ⚠️ 刻意只用 `torch.empty` + triton store, 不做任何 torch 数学 —— 候选臂整个跑在
# 反作弊的 shield 里, 写成 `C + w.to(...)` 会被判成 CheatDetectedError 而不是量出显存。
MM_WASTEFUL = '''
import torch, triton, triton.language as tl

@triton.jit
def _mmw(A, B, C, W, M, N, K, BM: tl.constexpr, BN: tl.constexpr, BK: tl.constexpr):
    pm = tl.program_id(0); pn = tl.program_id(1)
    om = pm * BM + tl.arange(0, BM); on = pn * BN + tl.arange(0, BN)
    acc = tl.zeros((BM, BN), dtype=tl.float32)
    for k0 in range(0, K, BK):
        ok = k0 + tl.arange(0, BK)
        a = tl.load(A + om[:, None] * K + ok[None, :])
        b = tl.load(B + ok[:, None] * N + on[None, :])
        acc = tl.dot(a, b, acc)
    tl.store(C + om[:, None] * N + on[None, :], acc.to(C.dtype.element_ty))
    tl.store(W + om[:, None] * N + on[None, :], acc)

def kernel(A, B):
    M, K = A.shape; N = B.shape[1]
    C = torch.empty((M, N), device=A.device, dtype=A.dtype)
    W = torch.empty((M, N), device=A.device, dtype=torch.float32)
    _mmw[(M // 64, N // 64)](A, B, C, W, M, N, K, BM=64, BN=64, BK=32)
    return C
'''


def task(kernel_type, precision):
    return TaskSchema(
        task_id="peak", task_type=TaskType.OPERATOR_GENERATION,
        source=SourceSpec(kernel_type=kernel_type, complexity=TaskComplexity.MEDIUM),
        target=TargetSpec(hardware="nvidia_gpu", dsl="triton", compute_units=78, warp_size=32),
        constraints=ConstraintSpec(precision=precision, min_speedup=0.0, max_error=1.0))


def mm_inputs(n, dtype):
    rng = np.random.default_rng(7)
    s = 0.1 / (n ** 0.5)
    return {"A": (rng.standard_normal((n, n)) * s).astype(dtype),
            "B": (rng.standard_normal((n, n)) * s).astype(dtype)}


def ln_inputs(rows, cols):
    rng = np.random.default_rng(11)
    return {"X": rng.standard_normal((rows, cols)).astype(np.float16),
            "weight": np.ones(cols, dtype=np.float16),
            "bias": np.zeros(cols, dtype=np.float16)}


LN = '''
import torch, triton, triton.language as tl

@triton.jit
def _ln(x_ptr, w_ptr, b_ptr, y_ptr, n_cols, eps, BLOCK: tl.constexpr):
    row = tl.program_id(0)
    cols = tl.arange(0, BLOCK)
    mask = cols < n_cols
    x = tl.load(x_ptr + row * n_cols + cols, mask=mask, other=0.0).to(tl.float32)
    mean = tl.sum(x, axis=0) / n_cols
    xc = tl.where(mask, x - mean, 0.0)
    rstd = 1.0 / tl.sqrt(tl.sum(xc * xc, axis=0) / n_cols + eps)
    w = tl.load(w_ptr + cols, mask=mask, other=0.0).to(tl.float32)
    b = tl.load(b_ptr + cols, mask=mask, other=0.0).to(tl.float32)
    tl.store(y_ptr + row * n_cols + cols, (xc * rstd * w + b).to(y_ptr.dtype.element_ty), mask=mask)

def kernel(X, weight, bias):
    M, N = X.shape
    Y = torch.empty_like(X)
    _ln[(M,)](X, weight, bias, Y, N, 1e-5, BLOCK=triton.next_power_of_2(N))
    return Y
'''

CASES = [
    ("标定臂: 已知多分配 4.0 MiB 的 fp16 matmul 1024²",
     MM_WASTEFUL, "matmul", Precision.FP16, mm_inputs(1024, np.float16), 4.0),
    ("合法 fp16 matmul 4096³ (期望 ratio≈1)",
     MM, "matmul", Precision.FP16, mm_inputs(4096, np.float16), None),
    ("fp32 matmul 1024³ (复核基线是否落在 tf32 档)",
     MM, "matmul", Precision.FP32, mm_inputs(1024, np.float32), None),
    ("layernorm 16384×6144 (访存密集, 输出与输入同尺寸)",
     LN, "layernorm", Precision.FP16, ln_inputs(16384, 6144), None),
]

backend = RemoteExecutor(mode="ssh")
print("=== deploy ===")
if not backend.deploy():
    sys.exit(1)
v = Verifier(backend)

bad = 0
for label, code, kt, prec, inputs, expect_extra_mib in CASES:
    r = v._verify_performance(code, inputs, 0.0, task(kt, prec))
    m = r.metrics or {}
    cp, bp = m.get("candidate_peak_memory_bytes"), m.get("baseline_peak_memory_bytes")
    print(f"\n{label}")
    print(f"  基线选中: {m.get('baseline_type')}   speedup={m.get('speedup_vs_baseline')}")
    if cp is None or bp is None:
        print("  ❌ 峰值显存没进 metrics —— 这条吸纳在远程路径上是空转的")
        bad += 1
        continue
    print(f"  额外峰值显存: 候选 {cp / 1048576:.2f} MiB / 基线 {bp / 1048576:.2f} MiB"
          f"   ratio={m.get('peak_memory_ratio')}")
    if expect_extra_mib is not None:
        extra_mib = (cp - bp) / 1048576
        ok = abs(extra_mib - expect_extra_mib) <= 0.6
        print(f"  标定: 候选比基线多 {extra_mib:.2f} MiB, 理论 {expect_extra_mib:.1f} MiB "
              f"→ {'✓ 量具看得见已知的那份分配' if ok else '❌ 量具看不见, 全部 ratio 作废'}")
        if not ok:
            bad += 1
    if kt == "matmul" and prec == Precision.FP32:
        ok = m.get('baseline_type') == "pytorch_eager_tf32"
        print(f"  TF32 复核: {'✓ 与 KernelBench-Verified 的口径一致' if ok else '❌ fp32 matmul 没比 TF32 基线 —— 加速比会被高估'}")
        if not ok:
            bad += 1

print("\n=== A/B: 同一个 fp32 核, 只换基线档位 ===")
print("  (这就是 KernelBench-Verified 那句 1.43x → 0.88x 在我们这条流水线上的本地版本)")
for prio, tag in ((["pytorch_eager_tf32", "pytorch_eager"], "TF32 基线 (现实口径)"),
                  (["pytorch_eager"], "非 TF32 基线 (KernelBench 原来的口径)")):
    b = backend.benchmark_with_baselines(MM, mm_inputs(1024, np.float32), "matmul",
                                         precision="fp32", baseline_priority=prio)
    sel = b.get("baseline_selected")
    cand = (b.get("candidate") or {})
    base = (b.get("baselines") or {}).get(sel) or {}
    cm, bm = cand.get("median_time_ms"), base.get("median_time_ms")
    sp = (bm / cm) if cm and bm else None
    print(f"  {tag}: selected={sel}  候选 {cm} ms / 基线 {bm} ms → speedup={sp}")

print("\n=== 结论 ===")
print("✅ 全部通过" if bad == 0 else f"❌ {bad} 项不通过")
print("""
改判条件 (什么时候该给它加阈值/判定):
  1. 标定臂量不出已知的 4.0 MiB  → 先修量具, 别谈判据。
  2. 合法核的 ratio 普遍在 1.0 附近 (±10%) → 说明观测可用, 可以开始攒分布;
     攒到几十个真机样本之后再谈「超过多少算退化」。
  3. 若发现候选普遍**低于**基线 (ratio<1) → 口径有问题 (比如基线多算了输出拷贝),
     先查口径再引用数字。
  4. 一旦语料 (docs/research/43 的 JSONL) 里出现 ratio 明显 >1 的核, 就要把它接进
     `measurement.persist_decision` —— 那时它才有资格当判决输入。
""")
sys.exit(1 if bad else 0)
